const fs = require('fs');
const MAP = '/data/shared/dashboard';
const NOTAMAIL_PATH = MAP + '/notamail.json';
const VRAGEN_PATH = MAP + '/vragen.json';
const PDF_NAAM = 'notamail.pdf';

// Alleen een ontbrekend bestand telt als 'nog niets geplaatst'. Elke andere
// leesfout (EIO als macOS het bestand naar iCloud heeft weggeschreven) gooien we
// door: anders zou de volgende opslag de bestaande inhoud met een lege lijst
// overschrijven.
function lees(pad, standaard) {
  try { return JSON.parse(fs.readFileSync(pad, 'utf8')); } catch (err) {
    if (err.code === 'ENOENT') return standaard;
    throw new Error('Kon ' + pad.split('/').pop() + ' niet lezen: ' + err.message);
  }
}

// Eerst naar een tijdelijk bestand en dan hernoemen: een afgebroken schrijfactie
// laat zo nooit een half JSON-bestand achter.
function schrijfRuw(pad, data) {
  fs.mkdirSync(MAP, { recursive: true });
  const tmp = pad + '.' + Date.now() + '.tmp';
  fs.writeFileSync(tmp, data);
  fs.renameSync(tmp, pad);
}

function schrijf(pad, inhoud) {
  schrijfRuw(pad, JSON.stringify(inhoud, null, 2) + '\n');
}

function tekst(waarde, max) {
  return String(waarde == null ? '' : waarde).replace(/\r\n/g, '\n').trim().slice(0, max);
}

// Het veld 'data' bevat de invoer als JSON-string (form-urlencoded, zo
// vermijden we een CORS-preflight).
function invoer() {
  const body = $json.body || {};
  if (typeof body.data === 'string') return JSON.parse(body.data);
  if (body.data && typeof body.data === 'object') return body.data;
  return body;
}

// Verwachte fouten als {success:false} teruggeven: een throw levert bij
// responseMode=responseNode een leeg 200-antwoord op.
try {
  const vragen = lees(VRAGEN_PATH, { vragen: [] }).vragen;
  return [{ json: {
    success: true,
    notamail: lees(NOTAMAIL_PATH, null),
    vragen: Array.isArray(vragen) ? vragen : [],
  } }];
} catch (err) {
  return [{ json: { success: false, error: err.message } }];
}

