  schrijfRuw(pad, JSON.stringify(inhoud, null, 2) + '\n');
}

function tekst(waarde, max) {
  return String(waarde == null ? '' : waarde).replace(/\r\n/g, '\n').trim().slice(0, max);
}

// Het veld 'data' bevat de invoer als JSON-string (form-urlencoded, zo
// vermijden we een CORS-preflight).
function invoer() {
  const body = $json.body || {};
  if (typeof body.data === 'string') return JSON.parse(body.data);
  if (body.data && typeof body.data === 'object') return body.data;
  return body;
}

const MAX_VRAGEN = 200;

let inv;
try { inv = invoer(); } catch (err) {
  return [{ json: { success: false, error: 'Ongeldige invoer: ' + err.message } }];
}

function fout(melding) { return [{ json: { success: false, error: melding } }]; }
// crypto is niet beschikbaar in de sandbox; tijd + toeval is hier uniek genoeg.
function nieuwId() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }

let vragen;
try { vragen = lees(VRAGEN_PATH, { vragen: [] }).vragen; } catch (err) { return fout(err.message); }
if (!Array.isArray(vragen)) vragen = [];

const actie = String(inv.actie || '');
const nu = new Date().toISOString();
const vraag = vragen.find((v) => v.id === inv.vraag_id);

if (actie === 'nieuw') {
  const inhoud = tekst(inv.tekst, 4000);
  const auteur = tekst(inv.auteur, 60);
  if (!inhoud) return fout('De vraag is leeg.');
  if (!auteur) return fout('Vul je naam in.');
  vragen.unshift({ id: nieuwId(), auteur, tekst: inhoud, geplaatst_op: nu, opgelost: false, reacties: [] });
  vragen = vragen.slice(0, MAX_VRAGEN);
} else if (actie === 'reactie') {
  const inhoud = tekst(inv.tekst, 4000);
  const auteur = tekst(inv.auteur, 60);
  if (!vraag) return fout('Deze vraag bestaat niet meer.');
  if (!inhoud) return fout('De reactie is leeg.');
  if (!auteur) return fout('Vul je naam in.');
  if (!Array.isArray(vraag.reacties)) vraag.reacties = [];
  vraag.reacties.push({ id: nieuwId(), auteur, tekst: inhoud, geplaatst_op: nu });
} else if (actie === 'opgelost') {
  if (!vraag) return fout('Deze vraag bestaat niet meer.');
  vraag.opgelost = Boolean(inv.opgelost);
} else if (actie === 'verwijderen') {
  if (!vraag) return fout('Deze vraag bestaat niet meer.');
  vragen = vragen.filter((v) => v.id !== vraag.id);
} else {
  return fout('Onbekende actie: ' + actie);
}

try { schrijf(VRAGEN_PATH, { vragen }); } catch (err) {
  return fout('Kon de vragen niet opslaan: ' + err.message);
}
return [{ json: { success: true, vragen } }];

