// vermijden we een CORS-preflight).
function invoer() {
  const body = $json.body || {};
  if (typeof body.data === 'string') return JSON.parse(body.data);
  if (body.data && typeof body.data === 'object') return body.data;
  return body;
}

const MAX_BYTES = 25 * 1024 * 1024;
function fout(melding) { return [{ json: { success: false, error: melding } }]; }

// Multipart: 'datum' en 'auteur' als gewone velden, de pdf als bestand 'file'.
const body = $json.body || {};
const datum = String(body.datum || '');
// De datum komt van de browser: de container draait in UTC en zou rond
// middernacht de verkeerde dag kiezen.
if (!/^\d{4}-\d{2}-\d{2}$/.test(datum)) return fout('Ongeldige datum.');

const binaries = $binary || {};
const sleutels = Object.keys(binaries);
const sleutel = binaries.file ? 'file' : (sleutels.length === 1 ? sleutels[0] : null);
if (!sleutel) return fout('Geen bestand gevonden in de upload.');

// $binary geeft alleen metadata; de inhoud komt via de helper binnen.
let buffer;
try {
  buffer = await this.helpers.getBinaryDataBuffer(0, sleutel);
} catch (err) {
  return fout('Kon het geuploade bestand niet lezen: ' + err.message);
}
if (!buffer || !buffer.length) return fout('Het geuploade bestand is leeg.');
if (buffer.length > MAX_BYTES) return fout('Het bestand is groter dan 25 MB.');
// Op de inhoud controleren, niet op de extensie: de pdf wordt straks door de
// webapp geserveerd en in de browser getoond.
if (buffer.subarray(0, 5).toString('latin1') !== '%PDF-') {
  return fout('Dit is geen pdf-bestand.');
}

const notamail = {
  datum,
  tekst: '',
  pdf: PDF_NAAM,
  bestandsnaam: tekst(binaries[sleutel].fileName || 'notamail.pdf', 200),
  geplaatst_door: tekst(body.auteur, 60),
  geplaatst_op: new Date().toISOString(),
};
try {
  schrijfRuw(MAP + '/' + PDF_NAAM, buffer);
  schrijf(NOTAMAIL_PATH, notamail);
} catch (err) {
  return fout('Kon de Notamail niet opslaan: ' + err.message);
}
return [{ json: { success: true, notamail } }];
